import { motion } from "framer-motion";
import { useState } from "react";

export default function Contact() {
  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    experience: "",
    specialization: "",
    message: "",
  });

  const [status, setStatus] = useState("");

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setStatus("Submitting...");

    try {
      const res = await fetch("http://localhost:5001/api/trainers/apply", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });

      if (res.ok) {
        setStatus("Application submitted successfully ✅");
        setForm({
          name: "",
          email: "",
          phone: "",
          experience: "",
          specialization: "",
          message: "",
        });
      } else {
        setStatus("Something went wrong ❌");
      }
    } catch (err) {
      setStatus("Server error ❌");
    }
  };

  return (
    <section
      id="contact"
      className="scroll-mt-24 bg-black py-32 px-6"
    >
      <div className="max-w-7xl mx-auto grid md:grid-cols-2 gap-16 items-center">

        {/* LEFT CONTENT */}
        <motion.div
          initial={{ opacity: 0, x: -50 }}
          whileInView={{ opacity: 1, x: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.7 }}
        >
          <h2 className="text-4xl md:text-5xl font-bold leading-tight">
            Become a <span className="text-[#e9b21a]">Bodyzeal Trainer</span>
          </h2>

          <p className="mt-6 text-gray-400 max-w-lg">
            Passionate about fitness? Ready to inspire, transform, and lead?
            We’re always looking for certified and motivated trainers to join
            the Bodyzeal Fitworks family.
          </p>

          <ul className="mt-8 space-y-3 text-gray-300 text-sm">
            <li>✔ Work with premium facilities & modern equipment</li>
            <li>✔ Grow your career with a fast-expanding fitness brand</li>
            <li>✔ Competitive pay & professional environment</li>
          </ul>

          <p className="mt-6 text-sm text-gray-500">
            Fill out the form and our management team will contact you.
          </p>
        </motion.div>

        {/* FORM */}
        <motion.form
          onSubmit={handleSubmit}
          initial={{ opacity: 0, x: 50 }}
          whileInView={{ opacity: 1, x: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.7 }}
          className="bg-zinc-900/70 border border-white/10 rounded-2xl p-10 space-y-5"
        >
          <input
            type="text"
            name="name"
            placeholder="Full Name"
            value={form.name}
            onChange={handleChange}
            required
            className="w-full bg-black border border-white/10 rounded-lg px-4 py-3 focus:border-[#e9b21a] outline-none"
          />

          <input
            type="email"
            name="email"
            placeholder="Email Address"
            value={form.email}
            onChange={handleChange}
            required
            className="w-full bg-black border border-white/10 rounded-lg px-4 py-3 focus:border-[#e9b21a] outline-none"
          />

          <input
            type="tel"
            name="phone"
            placeholder="Phone Number"
            value={form.phone}
            onChange={handleChange}
            required
            className="w-full bg-black border border-white/10 rounded-lg px-4 py-3 focus:border-[#e9b21a] outline-none"
          />

          <input
            type="text"
            name="experience"
            placeholder="Years of Experience (eg: 3 years)"
            value={form.experience}
            onChange={handleChange}
            required
            className="w-full bg-black border border-white/10 rounded-lg px-4 py-3 focus:border-[#e9b21a] outline-none"
          />

          <input
            type="text"
            name="specialization"
            placeholder="Specialization (PT, CrossFit, Zumba, Yoga, etc.)"
            value={form.specialization}
            onChange={handleChange}
            required
            className="w-full bg-black border border-white/10 rounded-lg px-4 py-3 focus:border-[#e9b21a] outline-none"
          />

          <textarea
            name="message"
            rows="4"
            placeholder="Tell us about yourself & certifications"
            value={form.message}
            onChange={handleChange}
            required
            className="w-full bg-black border border-white/10 rounded-lg px-4 py-3 focus:border-[#e9b21a] outline-none resize-none"
          />

          <button
            type="submit"
            className="w-full bg-[#e9b21a] hover:bg-[#d4a018] py-3 rounded-lg font-semibold transition"
          >
            Apply as Trainer
          </button>

          {status && (
            <p className="text-sm text-center text-gray-400">{status}</p>
          )}
        </motion.form>
      </div>

      <p className="mt-24 text-center text-sm text-gray-500">
        © 2025 Bodyzeal Fitworks. All rights reserved.
      </p>
    </section>
  );
}
